1	<!doctype html>
2	<html lang="sv">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>ALUNIX</title>
7	<link rel="stylesheet" href="assets/vendor/lenis.css">
8	
9	<style>
10	@font-face{
11	  font-family:"Geist";
12	  src:url("assets/fonts/geist-500-latin.woff2") format("woff2");
13	  font-weight:500; font-style:normal; font-display:swap;
14	}
15	@font-face{
16	  font-family:"Geist Mono";
17	  src:url("assets/fonts/geist-mono-400-latin.woff2") format("woff2");
18	  font-weight:400; font-style:normal; font-display:swap;
19	}
20	
21	:root{
22	  --paper:#ffffff;
23	  --ink:#232323;
24	  --black:#000000;
25	  --grey:#d9d9d9;
26	  --mint:#0af474;
27	  --mint-soft:#a3fbcb;
28	  --rust:#9c5a3a;
29	  --lacquer:#b23524;
30	  --seam:1px solid #000;
31	
32	  --headline-50:clamp(3.25rem, 0.418rem + 12.082vw, 12.5rem);
33	  --headline-40:clamp(2.5rem, 1.352rem + 4.9vw, 6.25rem);
34	  --headline-20:clamp(2rem, 1.694rem + 1.306vw, 3rem);
35	  --h3:38px;
36	  --body:16px;
37	  --body-30:clamp(1.5rem, 1.347rem + 0.653vw, 2rem);
38	  --caption:13px;
39	  --cellpad:20px;
40	}
41	
42	*{box-sizing:border-box;}
43	html{color-scheme:light;}
44	body{
45	  margin:0;
46	  background:#000;
47	  color:var(--ink);
48	  font-family:"Geist","Arial",system-ui,sans-serif;
49	  font-weight:500;
50	  line-height:1.3;
51	  -webkit-font-smoothing:antialiased;
52	  overflow-x:hidden;
53	}
54	img{display:block;max-width:100%;}
55	.mono{font-family:"Geist Mono","Consolas",monospace;font-weight:400;}
56	h1,h2,h3,p,ol,ul,figure{margin:0;padding:0;}
57	a{color:inherit;}
58	.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;}
59	
60	/* ---------------------------------------------------------- rutverket shell */
61	.rutverk{max-width:1440px;margin:0 auto;background:#000;}
62	.rutverk > section{scroll-margin-top:48px;}
63	
64	.g{display:grid;gap:1px;background:#000;}
65	.cell{background:var(--paper);padding:var(--cellpad);position:relative;overflow:hidden;}
66	.cell--pad0{padding:0;}
67	.cell--ink{background:var(--ink);color:var(--paper);}
68	.cell--black{background:var(--black);color:var(--paper);}
69	.cell--grey{background:var(--grey);color:var(--ink);}
70	.cell--mint{background:var(--mint);color:var(--black);}
71	.cell--rust{background:var(--rust);color:var(--paper);}
72	.cell--lacquer{background:var(--lacquer);color:var(--paper);}
73	
74	.g12{grid-template-columns:repeat(12,1fr);}
75	@media (max-width:1199px){
76	  .g12{grid-template-columns:repeat(6,1fr);}
77	}
78	@media (max-width:767px){
79	  .g12{grid-template-columns:1fr;}
80	  .g12 > *{grid-column:1 / -1 !important;}
81	}
82	
83	.c-2{grid-column:span 2;}
84	.c-3{grid-column:span 3;}
85	.c-4{grid-column:span 4;}
86	.c-5{grid-column:span 5;}
87	.c-6{grid-column:span 6;}
88	.c-7{grid-column:span 7;}
89	.c-8{grid-column:span 8;}
90	.c-12{grid-column:span 12;}
91	@media (max-width:1199px){
92	  .c-7,.c-5,.c-8,.c-4{grid-column:span 6;}
93	}
94	
95	.headline-50{font-size:var(--headline-50);line-height:.8;letter-spacing:-.04em;font-weight:500;}
96	.headline-40{font-size:var(--headline-40);line-height:1;letter-spacing:-.04em;font-weight:500;}
97	.headline-20{font-size:var(--headline-20);line-height:1;letter-spacing:-.04em;font-weight:500;}
98	.h3{font-size:var(--h3);line-height:1.1;letter-spacing:-.02em;font-weight:500;}
99	.body{font-size:var(--body);line-height:1.3;letter-spacing:-.02em;}
100	.body-30{font-size:var(--body-30);line-height:1.1;letter-spacing:-.02em;}
101	.caption{font-size:var(--caption);letter-spacing:0;}
102	.tnum{font-variant-numeric:tabular-nums;}
103	
104	/* ------------------------------------------------------------- topline */
105	.topline{
106	  position:sticky;top:0;z-index:40;height:48px;max-width:1440px;margin:0 auto;
107	  display:grid;grid-template-columns:auto 1fr auto;gap:1px;background:#000;
108	}
109	.topline-cell{background:var(--black);color:var(--paper);display:flex;align-items:center;padding:0 20px;}
110	.topline-logo{width:auto;height:22px;}
111	.topline-mark{font-size:15px;letter-spacing:-.02em;font-weight:500;}
112	.topline-mid{background:var(--paper);}
113	.topline-contact{background:var(--black);color:var(--paper);font-size:14px;text-decoration:none;justify-content:flex-end;}
114	
115	/* ------------------------------------------------------------- hero */
116	/* R3: the fixed 190svh CSS-sticky stage is gone. The pin distance is now
117	   owned by ScrollTrigger's own pinSpacing (desktop matchMedia branch,
118	   RORELSE-SPEC.md §2); hero-wrap just needs to size to its content so a
119	   no-JS/pre-JS view still shows one full stage, not a dead 90svh gap. */
120	.hero-wrap{position:relative;max-width:1440px;margin:0 auto;}
121	.hero-stage{
122	  position:relative;height:calc(100svh - 48px);
123	  display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;
124	  gap:1px;background:#000;
125	}
126	@media (max-width:767px){
127	  /* Mobile drops the pin: no extra scroll-span, no sticky stage. The four
128	     cells stack in normal flow (each already min-height:60vw, so the
129	     stack is naturally taller than one screen) and the card flips against
130	     that natural scroll distance instead of a dedicated dead-space span. */
131	  .hero-wrap{height:auto;}
132	  .hero-stage{grid-template-columns:1fr;grid-template-rows:repeat(4,minmax(60vw,auto));height:auto;position:relative;top:0;}
133	}
134	.hero-cell{position:relative;overflow:hidden;}
135	.hero-ov{background:var(--paper);display:flex;align-items:flex-end;padding:var(--cellpad);}
136	.hero-oh{background:var(--grey);}
137	.hero-nv{background:var(--grey);}
138	.hero-nh{background:var(--mint);}
139	.hero-h1{max-width:14ch;}
140	
141	.dither-layer{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
142	.color-layer{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
143	
144	/* card: a physical object (light stock, ink edge, hard offset shadow) so
145	   it reads against a black cell instead of disappearing into it. ~1.6x
146	   the R1 size at 1440 (was ~340px wide, now ~520px), 85:55 kept. */
147	.card-anchor{
148	  position:absolute;left:75%;top:50%;
149	  width:min(36vw,520px);
150	  aspect-ratio:85/55;
151	  transform:translate(-50%,-50%);
152	  perspective:1600px;
153	  z-index:5;
154	  pointer-events:none;
155	}
156	@media (max-width:767px){ .card-anchor{left:50%;top:120vw;width:min(74vw,380px);} }
157	.card-flip{
158	  width:100%;height:100%;position:relative;
159	  transform-style:preserve-3d;
160	  transform:rotateY(calc(var(--flip,0) * 180deg));
161	  box-shadow:10px 10px 0 0 #000;
162	}
163	.face{
164	  position:absolute;inset:0;
165	  background:#fff;
166	  backface-visibility:hidden;
167	  border:1px solid #000;
168	  overflow:hidden;
169	}
170	/* A visible white mat around the photo, not a full-bleed image: a card
171	   that is a photo edge-to-edge reads as "the photo", not as "a light
172	   stock object sitting on the cell" - the mat is what makes the white
173	   stock actually visible against a black ÖH ground. */
174	.face--front{background:#fff;padding:6%;}
175	/* R6 bugfix: kontakt's front is a <button> wrapping <span>s (spans, unlike
176	   hero's <div>s, default to display:inline) - an inline, merely
177	   position:relative .photo never gets a real box (width/height are ignored
178	   on non-replaced inline elements), so it collapsed to a ~2px sliver and
179	   the absolutely-positioned img inside inherited that zero-size containing
180	   block. display:block here makes both tags behave identically. */
181	.face--front .photo{display:block;position:relative;width:100%;height:100%;overflow:hidden;border:1px solid rgba(0,0,0,.5);}
182	.face--back{
183	  transform:rotateY(180deg);
184	  background:#fff;color:var(--ink);
185	  display:flex;flex-direction:column;justify-content:center;gap:10px;padding:6% 8%;
186	}
187	.face--front img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
188	.mark-dock{position:absolute;top:9%;left:9%;width:14%;z-index:2;}
189	.mark-dock svg{width:100%;height:auto;fill:#fff;filter:drop-shadow(0 0 3px rgba(0,0,0,.7));}
190	.card-mark{font-size:clamp(20px,2.6vw,32px);letter-spacing:-.02em;margin:0;}
191	.card-kicker{font-family:"Geist Mono";font-weight:400;font-size:clamp(11px,1.1vw,14px);opacity:.65;margin:2px 0 0;}
192	.card-rule{border:0;border-top:1px solid rgba(0,0,0,.25);margin:6px 0;width:100%;}
193	.card-services{display:flex;gap:10px;font-family:"Geist Mono";font-weight:400;font-size:clamp(10px,1.1vw,13px);}
194	.card-cta{font-size:clamp(13px,1.5vw,18px);text-decoration:underline;margin-top:4px;}
195	
196	/* ------------------------------------------------------------- tes */
197	.tes-top{background:var(--black);color:var(--paper);padding:calc(var(--cellpad)*2) var(--cellpad);}
198	.tes-top .headline-50{max-width:22ch;}
199	.tes-lower{min-height:104svh;}
200	.tes-stack{display:grid;grid-template-rows:repeat(3,1fr);gap:1px;background:#000;}
201	.tes-line{padding:var(--cellpad);display:flex;align-items:center;}
202	.tes-image{padding:0;}
203	
204	/* ------------------------------------------------------------- process */
205	.process-row{}
206	.process-left{background:var(--grey);}
207	.process-sticky{position:sticky;top:calc(48px + var(--cellpad));}
208	.process-kicker{margin-bottom:14px;}
209	.process-title{margin:0 0 18px;max-width:11ch;}
210	.process-lock{max-width:32ch;opacity:.8;}
211	.process-image{position:relative;margin-top:32px;aspect-ratio:1/1;width:100%;max-width:680px;border:1px solid #000;overflow:hidden;}
212	.process-right{background:var(--black);color:var(--paper);padding:0;}
213	.process-steps{list-style:none;}
214	.process-row-item{display:grid;grid-template-columns:56px 1fr;gap:14px;padding:22px var(--cellpad);border-top:1px solid #000;}
215	.process-row-item:first-child{border-top:none;}
216	.process-num{font-family:"Geist Mono";font-weight:400;font-size:13px;padding-top:4px;}
217	.process-step-title{margin:0 0 6px;}
218	.process-p{color:#bdbdbd;max-width:56ch;font-size:15px;}
219	
220	/* ------------------------------------------------------------- exempelcase */
221	/* R5 §A bugfix: 0.6x bottom padding (12px) was less than the SplitText
222	   mask-breathe allowance (0.16em, ~16-20px at this clamp size) needs to
223	   clear the word's own descenders before the cell's overflow:hidden edge
224	   - verify_motion.py's legibility scan caught the word's rendered box
225	   (with its mask wrapper's padding-bottom) genuinely sitting a few px
226	   below the cell's clip boundary at every scroll position (0vh visible,
227	   not >=40vh). Matching the top padding removes the clip entirely. */
228	.case-word-cell{padding:calc(var(--cellpad)*1.4) var(--cellpad) calc(var(--cellpad)*1.4 + 4px);overflow:hidden;}
229	.case-word-cell .headline-50{max-width:100%;}
230	
231	/* R5 §B1: väljaren - två knappar, skarpa 1440x900-vyer, ingen beskärande zoom */
232	.case-picker-cell{padding:0 var(--cellpad) calc(var(--cellpad)*1.2);background:#000;}
233	.case-picker{display:grid;gap:1px;background:#000;}
234	.case-choice{
235	  display:block;width:100%;margin:0;padding:0;border:0;background:var(--paper);color:inherit;
236	  font:inherit;text-align:left;cursor:pointer;-webkit-appearance:none;appearance:none;
237	}
238	.case-choice-frame{position:relative;display:block;aspect-ratio:16/10;overflow:hidden;background:var(--grey);}
239	.case-choice-frame img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transform:scale(1);transition:transform .7s cubic-bezier(.23,1,.32,1);will-change:transform;}
240	@media (hover:hover){
241	  .case-choice:hover .case-choice-frame img,
242	  .case-choice:focus-visible .case-choice-frame img{transform:scale(1.04);}
243	}
244	.case-choice:focus-visible{outline:2px solid var(--mint);outline-offset:-2px;}
245	.case-choice-meta{display:block;padding:16px var(--cellpad) 20px;border-bottom:4px solid transparent;}
246	.case-choice[aria-pressed="true"] .case-choice-meta{border-bottom-color:var(--mint);}
247	.case-choice-meta .h3{display:block;margin-bottom:4px;font-size:22px;}
248	
249	/* ------------------------------------------------------------- showcase (B2/C) */
250	.showcase-stage{display:grid;grid-template-columns:1fr;gap:1px;background:#000;}
251	@media (min-width:768px){ .showcase-stage{grid-template-columns:7fr 5fr;} }
252	.showcase-embed-cell{padding:0;background:var(--paper);position:relative;overflow:hidden;}
253	.showcase-embed-cell .showcase-frame-wrap{position:relative;width:100%;height:100%;overflow:hidden;background:var(--paper);}
254	.showcase-embed-cell .showcase-poster{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
255	.showcase-embed-cell iframe{
256	  position:absolute;top:0;left:0;width:1440px;height:900px;border:0;background:var(--paper);
257	  transform-origin:top left;pointer-events:none;opacity:0;
258	}
259	@media (max-width:767px){
260	  .showcase-embed-cell{position:sticky;top:48px;height:56svh;z-index:2;}
261	}
262	@media (min-width:768px){
263	  /* R6 §3, two stacked causes, both fixed here:
264	     1) .showcase-side's natural content (all 5/6 rows, R5's rise-mask kept
265	        every body visible at once) was taller than the embed cell's
266	        explicit height. A CSS grid item with an explicit height does not
267	        stretch to match a taller sibling's row track - the TRACK grows to
268	        fit the tall side instead, leaving the embed cell short of the
269	        row's actual height by the difference (measured ~110px), exposing
270	        the stage's own black gap background below the frame. Pinning both
271	        columns to the SAME explicit height (with the side's own
272	        overflow-y:auto as a never-clip safety net) makes them structurally
273	        impossible to mismatch, regardless of how much text a future edit
274	        adds.
275	     2) That explicit height was `100svh - 48px`, sized to sit BELOW the
276	        48px sticky topline - but the pin (`start:'top top'`) puts the
277	        section's rendered top at the viewport's own y:0, with the topline
278	        merely painted on top of (not offsetting) its first 48px. The
279	        result: content correctly avoids the topline visually, but then
280	        runs 48px short of the viewport's bottom edge, showing the stage's
281	        black background as a trailing band under both columns (measured:
282	        embed/side bottom at 852 of a 900-tall viewport). Hero's own pin
283	        has this identical 48px arithmetic and gap - invisible there only
284	        because it lands on the page's own black background either side.
285	        Showcase's is visible because there's real content flush above it.
286	        Fixed the same way hero's is invisible: fill the FULL viewport
287	        (100svh) - the topline still visually covers the top 48px (it's
288	        position:sticky, z-index:40, opaque), but the bottom now lands
289	        exactly on the viewport edge, so no gap is left to expose.
290	
291	     R7 runda 2, fynd 1: that "topline merely painted on top" claim was
292	     wrong for `.showcase-head`'s own rubrik - the topline IS opaque and
293	     DOES cover whatever renders in its first 48px; it just happened not to
294	     matter for hero (dark ground either side). Here `.showcase-head`'s
295	     headline-40 sits flush at the pinned section's very top edge, so its
296	     cap-height rendered UNDER the topline and got visually sheared (lead's
297	     through-05..through-12, 2026-09-25). Fix: pin the section 48px lower
298	     instead of hiding 48px under an opaque bar - `start:'top top+=48'` on
299	     the ScrollTrigger (setupDesktopEngine) puts the section's rendered top
300	     at y:48, exactly below the topline, and both cell heights shrink by
301	     the same 48px so the bottom still lands flush on the viewport edge -
302	     the R6 §3 gap this block fixed doesn't reopen, because now BOTH the
303	     offset and the height account for the topline, not just the height. */
304	  .showcase-embed-cell{height:calc(100svh - 48px);}
305	  .showcase-side{height:calc(100svh - 48px);overflow-y:auto;}
306	}
307	.showcase-side{display:grid;grid-template-rows:auto 1fr;gap:1px;background:#000;}
308	.showcase-panel{display:contents;}
309	.showcase-head{padding:calc(var(--cellpad)*1.4) var(--cellpad);}
310	.showcase-head .headline-40{margin-bottom:8px;}
311	
312	/* R7 §C: the accordion ledger (R6 §1/§2) is replaced on desktop by a single
313	   crossfading box - one background for the whole "ruta", every step
314	   grid-stacked in one cell and GSAP-scrubbed by the showcase pin's onUpdate
315	   (never a class-toggle). Mobile keeps R6's stacked-rows layout unchanged;
316	   only its opacity mechanism changes (measured contrast fix, see below). */
317	.showcase-row{padding:var(--cellpad);display:flex;flex-direction:column;justify-content:center;}
318	.showcase-row h3{margin-bottom:0;}
319	.showcase-row p{max-width:52ch;font-size:15px;margin-top:8px;}
320	
321	@media (min-width:768px){
322	  .showcase-rows{display:grid;grid-template-rows:auto 1fr;height:100%;}
323	  .showcase-panel--calyx .showcase-rows{background:var(--paper);color:var(--ink);}
324	  .showcase-panel--horai .showcase-rows{background:var(--black);color:var(--paper);}
325	  .showcase-panel--horai .showcase-row p{color:#bdbdbd;}
326	  .showcase-box-head{padding:var(--cellpad) var(--cellpad) 0;}
327	  .showcase-counter{display:block;font-size:13px;}
328	  .showcase-track{position:relative;height:4px;margin-top:10px;}
329	  .showcase-track::before{content:'';position:absolute;top:50%;left:0;right:0;height:1px;background:#000;transform:translateY(-50%);}
330	  .showcase-panel--horai .showcase-track::before{background:var(--paper);opacity:.3;}
331	  .showcase-track-fill{position:absolute;top:0;left:0;width:100%;height:4px;background:var(--mint);transform-origin:0 50%;transform:scaleX(0);}
332	  .showcase-steps{display:grid;height:100%;}
333	  /* R7 runda 2, fynd 3: leaden dömde rutan som "mest död svart yta" -
334	     stegtexten var liten (h3 38px flat, p 15px/52ch) och stod vertikalt
335	     centrerad i en hög, tom cell (through-05/through-08). Fixen har två
336	     delar: stegen flyttas högt (justify-content:flex-start, luft direkt
337	     under räknare+spår, aldrig centrerat), och skalan höjs till rutans egen
338	     nivå - h3 återanvänder headline-40-tokenet (klassen h3 står kvar, bara
339	     storleken byts, per uppdraget), p till 18px/44ch. */
340	  .showcase-row{grid-area:1/1;height:100%;justify-content:flex-start;padding-top:calc(var(--cellpad)*1.6);}
341	  .showcase-row h3{font-size:var(--headline-40);line-height:1.02;}
342	  .showcase-row p{font-size:18px;max-width:44ch;}
343	  /* Om text allena ändå lämnar rutans nedre del tom: en stor mono-siffra i
344	     nederkanten bär ytan typografiskt - samma siffra som räknaren
345	     (aria-hidden, ingen ny copy), tonad i takt med stegbytet i setStepState.
346	     Låg opacitet så den läses som en bakgrundstextur, inte en andra röst.
347	     .showcase-rows blir positioneringskontexten (hela rutan, huvud + steg)
348	     och beskär spillet - siffran får gärna gå av rutans nedre kant, samma
349	     "stor siffra möter kanten" som prisliggarens display-tal. */
350	  .showcase-rows{position:relative;overflow:hidden;}
351	  .showcase-box-number{
352	    position:absolute;left:var(--cellpad);bottom:calc(var(--cellpad)*-0.3);
353	    font-size:clamp(120px,22vw,220px);line-height:.78;letter-spacing:-.03em;
354	    opacity:0;pointer-events:none;user-select:none;
355	  }
356	  .showcase-panel--calyx .showcase-box-number{color:var(--ink);}
357	  .showcase-panel--horai .showcase-box-number{color:var(--paper);}
358	}
359	@media (max-width:767px){
360	  /* R7 runda 2, fynd 2: .showcase-embed-cell (position:sticky) satt över
361	     .showcase-side (head + rader) i normalt dokumentflöde, så när huvudet
362	     ("Hōrai") rullade upp genom den redan-klistrade ramen (z-index:2) klipptes
363	     det mot ramens underkant (lead: through-02/03). Huvudet ska stå helt
364	     synligt INNAN raderna - och innan ramen - börjar klistra, så .showcase-side
365	     görs display:contents här (bara mobil) för att lyfta .showcase-head och
366	     .showcase-rows till .showcase-stage's egna grid-items, och ordnas om med
367	     `order`: huvud (1) -> ram (2, där klistringen börjar) -> rader (3). */
368	  .showcase-side{display:contents;}
369	  .showcase-head{order:1;}
370	  .showcase-embed-cell{order:2;}
371	  .showcase-rows{display:flex;flex-direction:column;gap:1px;background:#000;order:3;}
372	  .showcase-box-head{display:none;}
373	  .showcase-steps{display:contents;}
374	  .showcase-panel--calyx .showcase-row:nth-child(odd){background:var(--paper);}
375	  .showcase-panel--calyx .showcase-row:nth-child(even){background:var(--grey);}
376	  .showcase-panel--horai .showcase-row:nth-child(odd){background:var(--black);color:var(--paper);}
377	  .showcase-panel--horai .showcase-row:nth-child(odd) p{color:#bdbdbd;}
378	  .showcase-panel--horai .showcase-row:nth-child(even){background:var(--grey);}
379	}
380	
381	/* ------------------------------------------------------------- pris */
382	.pris-statement{padding:calc(var(--cellpad)*2) var(--cellpad);}
383	.pris-statement .body-30{max-width:60ch;margin-top:16px;font-weight:500;}
384	/* All placement lives in these classes (not inline styles) so the media
385	   queries below can actually win the cascade at each breakpoint. */
386	.pris-bento{grid-template-columns:repeat(12,1fr);grid-template-rows:auto auto;}
387	.pris-lead{grid-column:1 / span 6;grid-row:1 / span 2;background:var(--mint);display:flex;flex-direction:column;justify-content:space-between;gap:24px;}
388	.pris-tier{display:flex;flex-direction:column;justify-content:space-between;gap:18px;min-height:220px;}
389	.pris-tier-a{grid-column:7 / span 6;grid-row:1;background:var(--paper);}
390	.pris-tier-b{grid-column:7 / span 6;grid-row:2;background:var(--grey);}
391	@media (max-width:1199px){
392	  .pris-bento{grid-template-columns:1fr 1fr;}
393	  .pris-lead{grid-column:1 / span 2;grid-row:1;}
394	  .pris-tier-a{grid-column:1;grid-row:2;}
395	  .pris-tier-b{grid-column:2;grid-row:2;}
396	}
397	@media (max-width:767px){
398	  .pris-bento{grid-template-columns:1fr;}
399	  .pris-lead,.pris-tier-a,.pris-tier-b{grid-column:1;grid-row:auto;min-height:0;}
400	}
401	.price-label{max-width:34ch;font-size:15px;}
402	.price-value{font-size:clamp(28px,3.6vw,44px);letter-spacing:-.03em;}
403	.price-value .unit{font-size:.5em;margin-left:2px;}
404	.price-value--text{font-size:clamp(18px,2vw,24px);}
