406	/* ------------------------------------------------------------- kontakt (R5 §C: heron speglad) */
407	.kontakt-quad{
408	  position:relative;display:grid;gap:1px;background:#000;min-height:100svh;
409	  grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;
410	  grid-template-areas:"ov oh" "nv nh";
411	}
412	.kontakt-q{position:relative;overflow:hidden;padding:var(--cellpad);}
413	.kontakt-q--ov{grid-area:ov;background:var(--black);color:var(--paper);display:flex;flex-direction:column;justify-content:flex-end;gap:10px;}
414	/* R6 §4: headline-40 is tuned for a single "jätteord" (hero, case names) -
415	   at this cell's half-page width, a four-word sentence in it ran past the
416	   ÖV/ÖH seam (measured x>720 at 1440, into the card's own space). A
417	   smaller, dedicated clamp - same family as the old kontakt-giant's - fits
418	   three lines comfortably inside the cell at 1440/1280/768, verified with
419	   getBoundingClientRect against the cell box, not eyeballed. */
420	.kontakt-q--ov h2{
421	  font-size:clamp(1.75rem, 1.1rem + 2.6vw, 3.4rem);line-height:1.05;
422	  letter-spacing:-.03em;font-weight:500;max-width:12ch;
423	}
424	.kontakt-q--ov p{max-width:32ch;font-size:15px;}
425	.kontakt-q--oh{grid-area:oh;background:var(--paper);}
426	.kontakt-q--nv{grid-area:nv;background:var(--grey);padding:0;}
427	.kontakt-q--nh{grid-area:nh;background:var(--mint);}
428	@media (max-width:767px){
429	  /* R6 §7: nh gets more room than ov/nv (was the same minmax(60vw) as
430	     both) - a 3D Y-axis rotation's perspective projection genuinely bulges
431	     a flat card's rendered bounding box taller at the near edge as it
432	     turns (measured: +/-28px top/bottom at 1200px perspective, still
433	     +/-24px at 3000px - foreshortening a rotated rectangle really does
434	     grow its axis-aligned bbox, not a rounding artefact), and centring an
435	     88%-wide card in a 60vw-tall row left only ~27px clearance to the
436	     subline above - not enough to survive that bulge at any angle in the
437	     0-180deg sweep. */
438	  .kontakt-quad{grid-template-columns:1fr;grid-template-rows:minmax(60vw,auto) minmax(76vw,auto) minmax(60vw,auto);grid-template-areas:"ov" "nh" "nv";min-height:auto;}
439	  .kontakt-q--oh{display:none;}
440	}
