442	/* the card sits on the crossing of all four quadrants (a grid item that
443	   spans the full 2x2 and centres itself), mirroring heron's own card. On
444	   mobile it drops into the mint cell's own grid area instead, 88% wide. */
445	/* R6 §4/§7: centred on the FULL 2x2 crossing put the card's top edge only
446	   ~15-50px below the headline row at rest, with zero margin for the flip's
447	   lift or the hover-tilt's foreshortening - both could (and did, measured)
448	   bring the card within single-digit px of "verksamhet.". Spanning only
449	   the LOWER row (grid-row:2, still centred horizontally on the vertical
450	   seam = still "on the crossing") puts the card inside the NV/NH half
451	   entirely, with a full row-height of clearance above it before ÖV even
452	   starts. */
453	.kontakt-card-anchor{
454	  grid-column:1 / 3;grid-row:2;place-self:center;z-index:5;
455	  width:min(32vw,460px);aspect-ratio:85/55;perspective:1200px;
456	}
457	@media (max-width:767px){
458	  .kontakt-card-anchor{grid-area:nh;place-self:center;width:80%;}
459	}
460	.kontakt-card-tilt{width:100%;height:100%;position:relative;transform-style:preserve-3d;}
461	.card-flip2{width:100%;height:100%;position:relative;transform-style:preserve-3d;box-shadow:10px 10px 0 0 #000;}
462	.card-flip2 button.face{margin:0;padding:6%;font:inherit;text-align:left;cursor:pointer;display:block;width:100%;height:100%;}
463	.card-flip2 button.face:focus-visible{outline:2px solid var(--mint);outline-offset:2px;}
464	.face-back-hit{position:absolute;inset:0;z-index:0;background:transparent;border:0;padding:0;margin:0;cursor:pointer;}
465	.face-back-hit:focus-visible{outline:2px solid var(--mint);outline-offset:2px;}
466	.card-back-content{position:relative;z-index:1;height:100%;display:flex;flex-direction:column;justify-content:center;gap:10px;pointer-events:none;}
467	.card-back-content a{pointer-events:auto;}
468	.card-back-links{display:flex;flex-direction:column;gap:6px;margin-top:4px;}
469	.card-back-links a{font-size:clamp(13px,1.5vw,18px);text-decoration:underline;width:max-content;}
