471	/* ------------------------------------------------------------- footer */
472	.footer-cell{background:var(--black);color:var(--paper);padding:0 0 0 var(--cellpad);height:34vw;max-height:340px;min-height:200px;display:flex;align-items:flex-end;overflow:hidden;}
473	.footer-mark{font-size:clamp(80px,16vw,220px);line-height:.8;letter-spacing:-.04em;white-space:nowrap;padding-bottom:.06em;}
474	.footer-strip{padding:18px var(--cellpad);background:var(--black);color:var(--paper);}
475	.footer-strip a{text-decoration:underline;font-size:14px;}
