477	/* ------------------------------------------------------------- resolve (dither -> color) */
478	.img-cell{position:relative;}
479	/* R3: §3 dither -> colour grid-stagger. The tile grid sits over the
480	   already-visible colour layer; each tile shows one slice of the dither
481	   image and fades on its own random-order schedule, so the resolve reads
482	   as pixels dissolving away rather than a wipe. Built once at init from
483	   the existing .dither-layer <img> (see buildTileGrid in the script). */
484	.tile-grid{position:absolute;inset:0;display:grid;pointer-events:none;}
485	.tile-grid > span{display:block;background-repeat:no-repeat;will-change:opacity;}
486	.color-layer{clip-path:none;}
487	
488	/* R3: seam-anchored decorations, all created/positioned by the script. */
489	.seam-line{position:absolute;background:var(--mint);pointer-events:none;z-index:3;}
490	/* the crosshair seam-draw is a 2x2-grid flourish; hero-stage stacks to one
491	   column under 768px (see .hero-stage media query above), so the same
492	   absolute-positioned lines would otherwise bisect the whole stacked
493	   column top to bottom - hide them there. */
494	@media (max-width:767px){ .seam-line{display:none;} }
495	.process-row{position:relative;}
496	.process-progress{position:absolute;top:0;bottom:0;width:2px;background:var(--mint);transform:scaleY(0);transform-origin:top center;pointer-events:none;z-index:6;}
497	/* process-left/process-right only sit side by side at the 1200px+ 12-col
498	   grid (BYGGSPEC .g12 breakpoints); below that they stack, so the seam
499	   the progress line marks no longer exists - hide it rather than let a
500	   stale left-offset poke 2px past the right edge (390/768 overflow). */
501	@media (max-width:1199px){ .process-progress{display:none;} }
502	
503	/* R3: SplitText's own mask:'lines'/'words'/'chars' option wraps each split
504	   unit in its own clipping span, and every heading that gets split already
505	   sits inside a .cell (overflow:hidden) or .footer-cell (overflow:hidden)
506	   — so no extra clip rule is needed on the headings themselves (adding one
507	   risked cutting descenders that round 2's static layout already relies
508	   on fitting without it). */
509	
510	/* spacing rhythm between section groups */
511	.rhythm{height:110px;}
512	@media (max-width:767px){ .rhythm{height:72px;} }
513	</style>
