  .showcase-counter{display:block;font-size:13px;}
  .showcase-track{position:relative;height:4px;margin-top:10px;}
  .showcase-track::before{content:'';position:absolute;top:50%;left:0;right:0;height:1px;background:#000;transform:translateY(-50%);}
  .showcase-panel--horai .showcase-track::before{background:var(--paper);opacity:.3;}
  .showcase-track-fill{position:absolute;top:0;left:0;width:100%;height:4px;background:var(--mint);transform-origin:0 50%;transform:scaleX(0);}
  .showcase-steps{display:grid;height:100%;}
  /* R7 runda 2, fynd 3: leaden dömde rutan som "mest död svart yta" -
     stegtexten var liten (h3 38px flat, p 15px/52ch) och stod vertikalt
     centrerad i en hög, tom cell (through-05/through-08). Fixen har två
     delar: stegen flyttas högt (justify-content:flex-start, luft direkt
     under räknare+spår, aldrig centrerat), och skalan höjs till rutans egen
     nivå - h3 återanvänder headline-40-tokenet (klassen h3 står kvar, bara
     storleken byts, per uppdraget), p till 18px/44ch. */
  .showcase-row{grid-area:1/1;height:100%;justify-content:flex-start;padding-top:calc(var(--cellpad)*1.6);}
  .showcase-row h3{font-size:var(--headline-40);line-height:1.02;}
  .showcase-row p{font-size:18px;max-width:44ch;}
  /* Om text allena ändå lämnar rutans nedre del tom: en stor mono-siffra i
     nederkanten bär ytan typografiskt - samma siffra som räknaren
     (aria-hidden, ingen ny copy), tonad i takt med stegbytet i setStepState.
     Låg opacitet så den läses som en bakgrundstextur, inte en andra röst.
     .showcase-rows blir positioneringskontexten (hela rutan, huvud + steg)
     och beskär spillet - siffran får gärna gå av rutans nedre kant, samma
     "stor siffra möter kanten" som prisliggarens display-tal. */
  .showcase-rows{position:relative;overflow:hidden;}
  .showcase-box-number{
    position:absolute;left:var(--cellpad);bottom:calc(var(--cellpad)*-0.3);
    font-size:clamp(120px,22vw,220px);line-height:.78;letter-spacing:-.03em;
    opacity:0;pointer-events:none;user-select:none;
  }
  .showcase-panel--calyx .showcase-box-number{color:var(--ink);}
  .showcase-panel--horai .showcase-box-number{color:var(--paper);}
}

