    b = p.chromium.launch(headless=True, channel="chromium", args=["--enable-gpu","--ignore-gpu-blocklist","--use-angle=d3d11"])
    pg = b.new_page(viewport={"width":1440,"height":900})
    pg.add_init_script("""
      window.__longtasks = [];
      try {
        new PerformanceObserver((list) => {
          list.getEntries().forEach(e => window.__longtasks.push({start: e.startTime, dur: e.duration, name: e.name}));
        }).observe({entryTypes: ['longtask']});
      } catch(e) { window.__po_error = String(e); }
    """)
    pg.goto(URL, wait_until="load", timeout=30000)
    pg.wait_for_timeout(1500)
    pg.evaluate("window.__lenis.scrollTo('#exempelcase',{immediate:true})")
    pg.wait_for_timeout(1500)
    pg.evaluate("window.__longtasks = []")  # clear pre-click noise
    t0 = pg.evaluate("performance.now()")
    pg.evaluate("document.querySelector('button.case-choice[data-case=horai]').click()")
    pg.wait_for_timeout(500)
    tasks = pg.evaluate("window.__longtasks")
    print("t0:", t0)
    print("po_error:", pg.evaluate("window.__po_error"))
    for t in tasks:
        print(f"  longtask start={t['start']-t0:.1f}ms dur={t['dur']:.1f}ms name={t['name']}")
    b.close()
EOF
