/* R4 §1: ease-in-out-cubic (var 1-2^(-10t), som la nästan hela rörelsen i
   de första bildrutorna) - t.ex. den mätta 629px-toppen. Samma kurva,
   duration 1.8 (var 1.4). */
function easeInOutCubic(t){ return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }

function activateCase(key, opts){
  opts = opts || {};
  var isNewSelection = key !== activeCaseKey;
  var prevKey = activeCaseKey;
  activeCaseKey = key;
  caseChoices.forEach(function(btn){ btn.setAttribute('aria-pressed', btn.getAttribute('data-case') === key ? 'true' : 'false'); });

  /* R4 §1: scrollen startas FÖRST, i klickets egen (nu tomma) bildruta -
     mätt (longtask-profil): den tunga panel-/iframe-/tidslinjearbetet
     nedan är i sig billigt (inga long tasks), grundorsaken satt i
     display:none -> '' som tvingade webbläsaren måla en tidigare aldrig
     renderad 1440x900-iframe första gången (fixat separat, se HTML:ens
     showcaseIframeHorai och tl.add nedan) - men resten flyttas ändå ut i
     en rAF så att scrollstarten aldrig kan blockeras av framtida arbete
     i den här funktionen. */
  if (opts.scroll !== false && lenis && lenis.scrollTo){
    lenis.scrollTo('#showcase', { duration: 1.8, easing: easeInOutCubic });
  }

  requestAnimationFrame(function(){
    var C = CASES[key], prevC = CASES[prevKey];

    if (isNewSelection){
      /* A#2: panel and iframe crossfade - old out 0.3s, new in 0.35s,
         power2.out, interruptible (overwrite:'auto'). Neither iframe is
         ever set to display:none after init (R4 §1) - both stay painted,
         hidden by opacity alone, so a later switch back never re-pays the
         first-paint cost. */
      C.el.style.display = '';
      C.el.toggleAttribute('inert', false);
      gsap.set(C.iframe, { opacity: 0 });
      if (C.head && C.box) gsap.set([C.head, C.box], { opacity: 0 });
      var tl = gsap.timeline({ overwrite: 'auto' });
      tl.to(prevC.iframe, { opacity: 0, duration: 0.3, ease: 'power2.out' }, 0);
      if (prevC.head && prevC.box) tl.to([prevC.head, prevC.box], { opacity: 0, duration: 0.3, ease: 'power2.out' }, 0);
      tl.to(C.iframe, { opacity: C.loaded ? 1 : 0, duration: 0.35, ease: 'power2.out' }, 0);
      if (C.head && C.box) tl.to([C.head, C.box], { opacity: 1, duration: 0.35, ease: 'power2.out' }, 0);
      tl.add(function(){
        prevC.el.style.display = 'none';
        prevC.el.toggleAttribute('inert', true);
      }, 0.3);
    }

    if (window.innerWidth >= 768){
      /* R7 bugfix: the persistent 'load' listener only backfills C.y/C.w
         when `activeCaseKey === C.key` - true for calyx at page load, but
         never true for a case idle-loaded in the background BEFORE it is
         first selected (activeCaseKey only becomes that key here, after
         'load' already fired once). Without this, C.y stays null forever
         and writeCaseScroll() no-ops silently: measured via showcase_probe -
         every run showed the newly-activated case's iframe scrollY frozen
         at 0 delta through the whole pin. measureCase() is cheap and
         idempotent, so it is safe to call on every activation, matching
         what the pre-refactor setupDesktopEngine(C) did per click (only the
         pin recreation - grundorsak 1 - is what is actually removed here). */
      measureCaseSettled(C);
      /* A#5: no ScrollTrigger.refresh() from the click. C changes and
         updateShowcase reads the pin's CURRENT progress, never resets to 0. */
      if (isNewSelection && showcaseST) updateShowcase(C, showcaseST.progress);
      scaleShowcaseFrame();
    } else {
      measureCaseSettled(C);
      if (isNewSelection){
        buildMobileRowTriggers(C);
        if (C.mobileTextEls) setMobileRowOpacity(C.mobileTextEls, 0);
      }
    }
  });
}

