     crossfadens tidslinje - GSAP läser inget nytt här eftersom opacity
     redan sattes explicit ovan), den andra bär läsningarna
     (measureCase/scaleShowcaseFrame) sedan webbläsaren haft en hel
     bildruta på sig att lägga den väntande layouten/målningen utan att
     bli avbruten av en tvingande läsning. */
  requestAnimationFrame(function(){
    var C = CASES[key], prevC = CASES[prevKey];
    var tl = null;

    if (isNewSelection){
      /* A#2: panel and iframe crossfade - old out 0.3s, new in 0.35s,
         power2.out, interruptible (overwrite:'auto'). display:none är
         vilolägets för iframes/panel igen (se ovan) - skrivs här, läses
         aldrig i samma bildruta. */
      C.el.style.display = '';
      C.el.toggleAttribute('inert', false);
      C.iframe.style.display = '';
      gsap.set(C.iframe, { opacity: 0 });
      if (C.head && C.box) gsap.set([C.head, C.box], { opacity: 0 });
