/* R5: förvärm en INAKTIV case's iframe en gång vid load - lägg ut, måla
   och avkoda den (visibility:visible en verklig stund, opacity kvar på 0
   så inget syns) medan läsaren bara scrollar förbi, långt innan ett klick
   kan hända. Håller den sedan i visibility:hidden (vilolägets, aldrig
   display:none - CDP-tracing visade att measureCase/paint/avkodning av en
   display:none-iframe är precis det som gav 470-536 ms-bildrutan, se
   RAPPORT.md R5). Skriver ingenting om casen redan hunnit aktiveras under
   förvärmningsfönstret. */
function prewarmInactiveCase(C){
  C.iframe.style.visibility = 'visible';
  gsap.set(C.iframe, { opacity: 0 });
  gsap.delayedCall(0.5, function(){
    if (activeCaseKey !== C.key) C.iframe.style.visibility = 'hidden';
  });
}

Object.keys(CASES).forEach(function(key){
  var C = CASES[key];
  if (!C.iframe) return;
  C.iframe.addEventListener('load', function(){
    measureCaseSettled(C);
    C.loaded = true;
    if (activeCaseKey === C.key){
      /* A#3: once loaded, the iframe fades in over 0.3s from behind its
         poster (SHOWCASE-SPEC §A) - the same duration whether this is the
         first real load or a later reload. */
      gsap.to(C.iframe, {
        opacity: 1, duration: 0.3, ease: 'power2.out', overwrite: 'auto',
        onComplete: function(){ if (C.poster) C.poster.style.display = 'none'; }
      });
      if (window.innerWidth >= 768){
        if (showcaseST) updateShowcase(C, showcaseST.progress);
      } else {
        tweenCaseTo(C, C.pendingRow || 0);
      }
    } else {
      prewarmInactiveCase(C);
    }
  });

