   (samma ursprung, `contentDocument` nåbart), den dokumenterade
   webbläsar-API:n för att tvinga fram och cacha avkodningen oavsett
   målningsstatus. visibility stannar 'visible' (mätt: measureCase
   behöver layout, inte målning - se separat fynd), opacity 0 tills
   klick. */
function prewarmInactiveCase(C){
  C.iframe.style.visibility = 'visible';
  var d = null, w = null;
  try { d = C.iframe.contentDocument; w = C.iframe.contentWindow; } catch (e) { d = null; }
  if (!d || !w) return;
  /* Hōrai (och katalogsajterna generellt) sätter sina foton som CSS
     background-image, inte <img> - `<img>.decode()` hittade noll element
     (mätt: d.images.length === 0), vilket är varför den vägen inte
     hjälpte. Bygg tysta Image()-objekt för varje unik background-image-
     URL i dokumentet i stället - webbläsarens avkodade bildcache delas
     per URL oavsett hur den refereras (<img> eller background-image). */
  var seen = {};
  Array.prototype.slice.call(d.querySelectorAll('*')).forEach(function(el){
    var bg = w.getComputedStyle(el).backgroundImage;
    var m = bg && /url\(["']?([^"')]+)["']?\)/.exec(bg);
    var url = m && m[1];
    if (url && !seen[url] && url.indexOf('data:') !== 0){
      seen[url] = true;
      var img = new Image();
      img.src = url;
      if (img.decode) img.decode().catch(function(){});
    }
  });
}

